{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "Bullying would mean an act by a school employee or student that substantially interferes with a victim’s educational benefits, opportunities, or performance. On school grounds, at a school-sponsored activity, using school-provided equipment or transportation, or at an official school bus stop, the act must physically harm the victim or damage the victim’s property, or knowingly place the victim in reasonable fear of such harm or damage. Off school property and outside school-sponsored activities, the act must be directed specifically at a victim and substantially disrupt the educational environment or learning process.",
      "rationale": "Conveys the actors, educational interference requirement, and harm and disruption conditions, but changes the off-site condition from off school property OR outside a school-sponsored activity to requiring both."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "A school employee would include employees of private schools, local education agencies, public charter schools, and other public schools.",
      "rationale": "Conveys all categories covered by the school employee definition."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "A victim would be any student when the act is by a school employee, and another student when the act is by a student.",
      "rationale": "Conveys both branches of the victim definition and their respective actors."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would add “school employee” after “each student” in a provision of Tennessee Code Annotated Section 49-6-4503(b)(3).",
      "rationale": "Identifies the precise amendment target and the addition of school employees alongside students."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "It would also make a teacher or school employee found to have committed harassment, intimidation, bullying, or cyberbullying subject to dismissal or suspension.",
      "rationale": "Conveys the covered employees, all four forms of misconduct, the required finding, and both possible employment consequences."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "It would also make a teacher or school employee found to have committed harassment, intimidation, bullying, or cyberbullying subject to dismissal or suspension. In Section 49-5-501(7), it would add committing one of those acts in violation of a school district policy adopted under Chapter 6, Part 45 as a new listed subdivision.",
      "rationale": "Identifies the amendment target and conveys the addition of the four acts when committed in violation of the specified district policy."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Beginning July 1, 2026, this bill would revise the definition of bullying and apply it to acts committed on or after that date.",
      "rationale": "Conveys the effective date and prospective application to acts committed on or after that date."
    }
  ]
}
